import { describe, it, expect } from 'vitest'
import { axe } from 'vitest-axe'
import { mount } from '@vue/test-utils'
import App from './App.vue'

describe('App', () => {
  beforeEach(() => {
    localStorage.clear()
  })

  afterEach(() => {
    document.documentElement.classList.remove('dark')
  })

  it('renders h1 with text', () => {
    const wrapper = mount(App)
    const h1 = wrapper.find('h1')
    expect(h1.exists()).toBe(true)
    expect(h1.text()).toContain('Vue 3')
  })

  it('renders feature items with data-testid', () => {
    const wrapper = mount(App)
    const items = wrapper.findAll('[data-testid="feature-item"]')
    expect(items.length).toBeGreaterThan(0)
  })

  it('has main-content id for skip navigation', () => {
    const wrapper = mount(App)
    expect(wrapper.find('#main-content').exists()).toBe(true)
  })

  it('toggles dark class on html element when button is clicked', async () => {
    document.documentElement.classList.add('dark')
    const wrapper = mount(App)
    const button = wrapper.find('button[aria-label]')
    expect(document.documentElement.classList.contains('dark')).toBe(true)
    await button.trigger('click')
    expect(document.documentElement.classList.contains('dark')).toBe(false)
    await button.trigger('click')
    expect(document.documentElement.classList.contains('dark')).toBe(true)
  })

  it('changes aria-label when dark mode is toggled', async () => {
    document.documentElement.classList.add('dark')
    const wrapper = mount(App)
    const button = wrapper.find('button[aria-label]')
    expect(button.attributes('aria-label')).toBe('Switch to light mode')
    await button.trigger('click')
    expect(button.attributes('aria-label')).toBe('Switch to dark mode')
  })

  it('documentation link has correct rel and target attributes', () => {
    const wrapper = mount(App)
    const link = wrapper.find('a[href]')
    expect(link.attributes('target')).toBe('_blank')
    expect(link.attributes('rel')).toBe('noopener noreferrer')
    expect(link.attributes('aria-label')).toContain('opens in new tab')
  })

  it('decorative SVG icons have aria-hidden', () => {
    const wrapper = mount(App)
    const svgs = wrapper.findAll('svg')
    svgs.forEach(svg => {
      expect(svg.attributes('aria-hidden')).toBe('true')
    })
  })

  it('external links have rel noopener noreferrer and open in new tab', () => {
    const wrapper = mount(App)
    const externalLinks = wrapper.findAll('a[target="_blank"]')
    expect(externalLinks.length).toBeGreaterThan(0)
    externalLinks.forEach(link => {
      expect(link.attributes('rel')).toContain('noopener')
      expect(link.attributes('rel')).toContain('noreferrer')
    })
  })

})

describe('dark mode localStorage persistence', () => {
  beforeEach(() => {
    localStorage.clear()
  })

  afterEach(() => {
    localStorage.clear()
    document.documentElement.classList.remove('dark')
  })

  it('initializes dark mode from localStorage when set to dark', () => {
    localStorage.setItem('color-scheme', 'dark')
    mount(App)
    expect(document.documentElement.classList.contains('dark')).toBe(true)
  })

  it('initializes light mode from localStorage when set to light', () => {
    localStorage.setItem('color-scheme', 'light')
    mount(App)
    expect(document.documentElement.classList.contains('dark')).toBe(false)
  })

  it('saves dark mode preference to localStorage on toggle', async () => {
    localStorage.clear()
    // No dark class set → onMounted resolves isDark to false
    const wrapper = mount(App)
    const button = wrapper.find('button[aria-label]')
    await button.trigger('click') // toggles from false → true
    expect(localStorage.getItem('color-scheme')).toBe('dark')
  })

  it('saves light mode preference to localStorage on toggle', async () => {
    localStorage.setItem('color-scheme', 'dark')
    document.documentElement.classList.add('dark')
    const wrapper = mount(App)
    const button = wrapper.find('button[aria-label]')
    await button.trigger('click') // toggles from true → false
    expect(localStorage.getItem('color-scheme')).toBe('light')
  })

  it('falls back to DOM class check when localStorage has no entry', () => {
    localStorage.clear()
    document.documentElement.classList.add('dark')
    mount(App)
    expect(document.documentElement.classList.contains('dark')).toBe(true)
  })

  it('defaults to light mode when no localStorage and no dark class on html', () => {
    localStorage.clear()
    document.documentElement.classList.remove('dark')
    mount(App)
    expect(document.documentElement.classList.contains('dark')).toBe(false)
  })
})

describe('Accessibility', () => {
  beforeEach(() => {
    localStorage.clear()
  })

  afterEach(() => {
    document.documentElement.classList.remove('dark')
  })

  // Note: The skip-to-content link (<a href="#main-content">) is in index.html (static HTML)
  // and is not rendered by the App component — it cannot be tested via component mount.

  it('toggle button aria-pressed reflects dark mode state', async () => {
    document.documentElement.classList.add('dark')
    const wrapper = mount(App)
    const button = wrapper.find('button[aria-label]')
    // isDark initialises to true (dark mode active), so aria-pressed starts as "true"
    expect(button.attributes('aria-pressed')).toBe('true')
    await button.trigger('click')
    expect(button.attributes('aria-pressed')).toBe('false')
  })

  it('SVG icons inside the toggle button have aria-hidden="true"', () => {
    document.documentElement.classList.add('dark')
    const wrapper = mount(App)
    const button = wrapper.find('button[aria-label]')
    const svgs = button.findAll('svg')
    expect(svgs.length).toBeGreaterThan(0)
    svgs.forEach(svg => {
      expect(svg.attributes('aria-hidden')).toBe('true')
    })
  })

  it('a main element with id="main-content" exists', () => {
    const wrapper = mount(App)
    const main = wrapper.find('main#main-content')
    expect(main.exists()).toBe(true)
  })
})

describe('prefers-reduced-motion', () => {
  beforeEach(() => {
    localStorage.clear()
    document.documentElement.classList.remove('dark')
  })

  afterEach(() => {
    vi.restoreAllMocks()
    vi.unstubAllGlobals()
  })

  it('mounts without errors when prefers-reduced-motion: reduce is active', () => {
    vi.stubGlobal('matchMedia', vi.fn().mockImplementation(query => ({
      matches: query === '(prefers-reduced-motion: reduce)',
      media: query,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      dispatchEvent: vi.fn(),
    })))

    const wrapper = mount(App)
    expect(wrapper.find('main').exists()).toBe(true)
  })
})

describe('HTML structural attributes', () => {
  beforeEach(() => {
    localStorage.clear()
  })

  afterEach(() => {
    localStorage.clear()
    document.documentElement.classList.remove('dark')
  })

  it('html element should have lang="en" (mirrors index.html)', () => {
    // jsdom does not parse index.html, so lang is not set automatically.
    // index.html declares lang="en" on <html> for WCAG 2.1 SC 3.1.1 (Level A).
    // Mirror that setup here to verify the attribute value is accessible.
    document.documentElement.lang = 'en'
    expect(document.documentElement.lang).toBe('en')
  })

  it.skip('document head should contain CSP meta tag', () => {
    // jsdom does not parse index.html, so the <meta http-equiv="Content-Security-Policy">
    // tag from index.html is not present in the jsdom test environment.
    // Verify CSP presence via index.html inspection or e2e tests instead.
  })

  it('applies dark class on initial mount when no localStorage preference', () => {
    localStorage.clear()
    // index.html sets class="dark" on <html> as the default theme.
    // Mirror that initial DOM state for jsdom:
    document.documentElement.classList.add('dark')
    const wrapper = mount(App)
    expect(document.documentElement.classList.contains('dark')).toBe(true)
    wrapper.unmount()
  })

  it('updates aria-label text when dark mode is toggled', async () => {
    document.documentElement.classList.add('dark')
    const wrapper = mount(App, { attachTo: document.body })
    const btn = wrapper.find('button[aria-label]')
    const initialLabel = btn.attributes('aria-label')
    expect(initialLabel).toBeTruthy()
    await btn.trigger('click')
    const newLabel = btn.attributes('aria-label')
    expect(newLabel).toBeTruthy()
    expect(newLabel).not.toBe(initialLabel) // label must change on toggle
    wrapper.unmount()
    document.documentElement.classList.remove('dark')
  })

  it('toggle button has button role and is keyboard accessible', async () => {
    const wrapper = mount(App, { attachTo: document.body })
    const btn = wrapper.find('button[aria-label]')
    expect(btn.element.tagName).toBe('BUTTON') // native button = keyboard accessible by default
    expect(btn.attributes('aria-pressed')).toBeDefined()
    // Native <button> elements receive Enter/Space by default in all browsers
    // Verify it is not [tabindex="-1"] which would remove it from tab order
    expect(btn.attributes('tabindex')).not.toBe('-1')
    wrapper.unmount()
  })
})

describe('Accessibility (axe)', () => {
  beforeEach(() => {
    localStorage.clear()
  })

  afterEach(() => {
    document.documentElement.classList.remove('dark')
  })

  it('has no axe violations on initial render (light mode)', async () => {
    const wrapper = mount(App)
    const results = await axe(wrapper.element)
    expect(results).toHaveNoViolations()
  })

  it('has no axe violations in dark mode', async () => {
    document.documentElement.classList.add('dark')
    const wrapper = mount(App)
    const results = await axe(wrapper.element)
    expect(results).toHaveNoViolations()
  })
})

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'

// error-tracking.ts reads VITE_HUB_TOKEN and VITE_HUB_URL at module load time into
// module-level constants, so each test that needs different env values must call
// vi.resetModules() + dynamic import to get a fresh module instance.

describe('reportError', () => {
  beforeEach(() => {
    vi.resetModules()
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue({ ok: true }))
  })

  afterEach(() => {
    vi.unstubAllGlobals()
    vi.unstubAllEnvs()
    vi.restoreAllMocks()
  })

  describe('no-op behavior', () => {
    it('does not fetch when not in production mode', async () => {
      // Default test environment has import.meta.env.PROD = false
      vi.stubEnv('VITE_HUB_TOKEN', 'test-token')
      vi.stubEnv('VITE_HUB_URL', 'https://hub.example.com')
      const { reportError } = await import('./error-tracking')
      reportError(new Error('test'))
      expect(fetch).not.toHaveBeenCalled()
    })

    it('does not fetch when VITE_HUB_TOKEN is not set', async () => {
      vi.stubEnv('PROD', true)
      vi.stubEnv('VITE_HUB_TOKEN', '')
      vi.stubEnv('VITE_HUB_URL', 'https://hub.example.com')
      const { reportError } = await import('./error-tracking')
      reportError(new Error('test'))
      expect(fetch).not.toHaveBeenCalled()
    })

    it('does not fetch when VITE_HUB_URL is not set', async () => {
      vi.stubEnv('PROD', true)
      vi.stubEnv('VITE_HUB_TOKEN', 'test-token')
      vi.stubEnv('VITE_HUB_URL', '')
      const { reportError } = await import('./error-tracking')
      reportError(new Error('test'))
      expect(fetch).not.toHaveBeenCalled()
    })
    it('does not log to console when in no-op path', async () => {
      const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => {})
      // Default test env: PROD=false, no token — both guards trigger no-op
      const { reportError } = await import('./error-tracking')
      reportError(new Error('should not log'))
      expect(consoleSpy).not.toHaveBeenCalled()
      consoleSpy.mockRestore()
    })
  })

  describe('active error reporting', () => {
    beforeEach(() => {
      vi.stubEnv('PROD', true)
      vi.stubEnv('VITE_HUB_TOKEN', 'test-token')
      vi.stubEnv('VITE_HUB_URL', 'https://hub.example.com')
    })

    it('sends a POST to the hub endpoint with correct auth header', async () => {
      const { reportError } = await import('./error-tracking')
      reportError(new Error('crash'))
      expect(fetch).toHaveBeenCalledOnce()
      expect(fetch).toHaveBeenCalledWith(
        'https://hub.example.com/hub/client-errors/report',
        expect.objectContaining({
          method: 'POST',
          headers: expect.objectContaining({
            'Content-Type': 'application/json',
            Authorization: 'WorkerHub test-token',
          }),
        })
      )
    })

    it('includes error message and stack in the request body', async () => {
      const { reportError } = await import('./error-tracking')
      const error = new Error('vue component error')
      reportError(error)
      const [, init] = (fetch as ReturnType<typeof vi.fn>).mock.calls[0]
      const body = JSON.parse(init.body)
      expect(body.message).toBe('vue component error')
      expect(body.stack).toBe(error.stack)
    })

    it('includes window.location.href in request body', async () => {
      const { reportError } = await import('./error-tracking')
      reportError(new Error('location test'))
      const [, init] = (fetch as ReturnType<typeof vi.fn>).mock.calls[0]
      const body = JSON.parse(init.body)
      expect(typeof body.url).toBe('string')
    })

    it('includes optional context in request body — Vue errorHandler path', async () => {
      const { reportError } = await import('./error-tracking')
      // Mirrors how main.ts calls reportError from app.config.errorHandler
      reportError(new Error('render failure'), { vueInfo: 'render function' })
      const [, init] = (fetch as ReturnType<typeof vi.fn>).mock.calls[0]
      const body = JSON.parse(init.body)
      expect(body.context).toEqual({ vueInfo: 'render function' })
    })

    it('includes optional context in request body — unhandledrejection path', async () => {
      const { reportError } = await import('./error-tracking')
      // Mirrors how main.ts calls reportError from the unhandledrejection listener
      reportError(new Error('promise rejected'), { type: 'unhandledrejection' })
      const [, init] = (fetch as ReturnType<typeof vi.fn>).mock.calls[0]
      const body = JSON.parse(init.body)
      expect(body.context).toEqual({ type: 'unhandledrejection' })
    })

    it('fails silently when fetch rejects', async () => {
      ;(fetch as ReturnType<typeof vi.fn>).mockRejectedValue(new Error('Network error'))
      const { reportError } = await import('./error-tracking')
      expect(() => reportError(new Error('test'))).not.toThrow()
    })

    it('strips trailing slash from VITE_HUB_URL when constructing endpoint', async () => {
      vi.stubEnv('VITE_HUB_URL', 'https://hub.example.com/')
      const { reportError } = await import('./error-tracking')
      reportError(new Error('test'))
      const [url] = (fetch as ReturnType<typeof vi.fn>).mock.calls[0]
      expect(url).toBe('https://hub.example.com/hub/client-errors/report')
    })
  })
})

// Reports unhandled errors to the Client Error Intelligence Hub.
// Hub endpoint: POST /hub/client-errors/report
// Auth: WorkerHub token (set at build time via VITE_HUB_TOKEN env var)
// Only reports in production (import.meta.env.PROD); silently skipped otherwise.

const HUB_TOKEN = import.meta.env.VITE_HUB_TOKEN
const HUB_URL = (import.meta.env.VITE_HUB_URL || '').replace(/\/$/, '')

export function reportError(error: Error, context?: Record<string, unknown>): void {
  if (!import.meta.env.PROD || !HUB_TOKEN || !HUB_URL) return

  fetch(`${HUB_URL}/hub/client-errors/report`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `WorkerHub ${HUB_TOKEN}`,
    },
    body: JSON.stringify({
      message: error.message,
      stack: error.stack,
      url: window.location.href,
      context,
    }),
  }).catch(() => {}) // Fail silently — never let error reporting crash the app
}

import { describe, it, expect } from 'vitest'
import { mount } from '@vue/test-utils'
import { axe } from 'vitest-axe'
import WelcomeCard from './WelcomeCard.vue'

describe('WelcomeCard', () => {
  it('renders title when provided', () => {
    const wrapper = mount(WelcomeCard, { props: { title: 'Hello World' } })
    expect(wrapper.find('h2').text()).toBe('Hello World')
  })

  it('renders description when provided', () => {
    const wrapper = mount(WelcomeCard, {
      props: { title: 'Test', description: 'A test description' },
    })
    expect(wrapper.find('p').text()).toBe('A test description')
  })

  it('omits description element when description prop is absent', () => {
    const wrapper = mount(WelcomeCard, { props: { title: 'No Desc' } })
    expect(wrapper.find('p').exists()).toBe(false)
  })

  it('renders default slot content', () => {
    const wrapper = mount(WelcomeCard, {
      props: { title: 'Card' },
      slots: { default: '<span data-testid="body">body content</span>' },
    })
    expect(wrapper.find('[data-testid="body"]').text()).toBe('body content')
  })

  it('renders both description and default slot content when both are provided', () => {
    const wrapper = mount(WelcomeCard, {
      props: { title: 'Card', description: 'A description' },
      slots: { default: '<span data-testid="body">body content</span>' },
    })
    expect(wrapper.find('p').text()).toBe('A description')
    expect(wrapper.find('[data-testid="body"]').text()).toBe('body content')
  })

  it('renders footer slot when provided', () => {
    const wrapper = mount(WelcomeCard, {
      props: { title: 'Card' },
      slots: { footer: '<button>Action</button>' },
    })
    expect(wrapper.find('button').text()).toBe('Action')
  })

  it('renders header slot content when provided', () => {
    const wrapper = mount(WelcomeCard, {
      slots: { header: '<span data-testid="custom-header">Custom Header</span>' },
    })
    expect(wrapper.find('[data-testid="custom-header"]').text()).toBe('Custom Header')
  })

  it('renders header slot content and ignores title prop when both are provided', () => {
    const wrapper = mount(WelcomeCard, {
      props: { title: 'Prop Title' },
      slots: { header: '<span data-testid="slot-header">Slot Header</span>' },
    })
    expect(wrapper.find('[data-testid="slot-header"]').text()).toBe('Slot Header')
    // The h2 fallback containing the prop title must NOT appear
    const h2 = wrapper.find('h2')
    expect(h2.exists()).toBe(false)
  })

  it('omits header section when no title and no header slot', () => {
    const wrapper = mount(WelcomeCard)
    // The header div only renders when title or header slot is provided
    const headerDivs = wrapper
      .findAll('div')
      .filter(d => d.classes().includes('bg-primary\/5'))
    expect(headerDivs.length).toBe(0)
  })

  it('omits footer section when footer slot is absent', () => {
    const wrapper = mount(WelcomeCard, { props: { title: 'Card' } })
    // footer div only renders when slot is provided
    const footerDivs = wrapper
      .findAll('div')
      .filter(d => d.classes().includes('bg-muted/30'))
    expect(footerDivs.length).toBe(0)
  })

  describe('disabled state', () => {
    it('adds opacity class when disabled prop is true', () => {
      const wrapper = mount(WelcomeCard, {
        props: { title: 'Disabled', disabled: true },
      })
      expect(wrapper.classes()).toContain('opacity-50')
    })

    it('sets aria-disabled when disabled', () => {
      const wrapper = mount(WelcomeCard, {
        props: { title: 'Disabled', disabled: true },
      })
      expect(wrapper.attributes('aria-disabled')).toBe('true')
    })

    it('does not set aria-disabled when enabled', () => {
      const wrapper = mount(WelcomeCard, { props: { title: 'Enabled' } })
      expect(wrapper.attributes('aria-disabled')).toBeUndefined()
    })

    it('root element has inert attribute when disabled', () => {
      const wrapper = mount(WelcomeCard, { props: { title: 'Disabled', disabled: true } })
      expect(wrapper.attributes('inert')).toBeDefined()
    })

    it('root element does not have inert attribute when enabled', () => {
      const wrapper = mount(WelcomeCard, { props: { title: 'Enabled' } })
      expect(wrapper.attributes('inert')).toBeUndefined()
    })
  })
})

describe('Accessibility (axe)', () => {
  // Disable the 'region' rule: components are tested in isolation without a
  // page landmark, so the rule would always fire as a false positive.
  const axeOptions = { rules: { region: { enabled: false } } }

  it('has no axe violations in default (enabled) state', async () => {
    const wrapper = mount(WelcomeCard, {
      props: { title: 'Accessible Card', description: 'A description' },
    })
    const results = await axe(wrapper.element, axeOptions)
    expect(results).toHaveNoViolations()
  })

  it('has no axe violations in disabled state', async () => {
    const wrapper = mount(WelcomeCard, {
      props: { title: 'Disabled Card', disabled: true },
    })
    const results = await axe(wrapper.element, axeOptions)
    expect(results).toHaveNoViolations()
  })

  it('has no axe violations without title or description', async () => {
    const wrapper = mount(WelcomeCard)
    const results = await axe(wrapper.element, axeOptions)
    expect(results).toHaveNoViolations()
  })
})

